  status: { type: String, enum: ['active', 'staged', 'retired'], default: 'active' },
  trainingRows: { type: Number }
});

// DecisionTrace is the Autonomous Store Manager's memory: every decision it makes,
// why it made it, what it expected, what actually happened, and what it learned.
const decisionTraceSchema = new mongoose.Schema({
  id: { type: String, required: true },
  shopId: { type: String, required: true },
  cycleId: { type: String, required: true },
  stage: { type: String, enum: ['observe', 'understand', 'evaluate', 'diagnose', 'optimize', 'execute', 'learn'], required: true },
  goal: { type: String, enum: ['reduce_stockouts', 'increase_profit', 'recover_udhaar', 'reduce_dead_inventory'] },
  decision: { type: String }, // e.g. "Order 25 Milk packets"
  reason: [{
    factor: { type: String },
    value: { type: mongoose.Schema.Types.Mixed }
  }],
  confidence: { type: Number }, // 0-100
  simulation: {
    noActionOutcome: { type: String },
    noActionImpact: { type: Number },
    actionOutcome: { type: String },
    actionImpact: { type: Number }
  },
  expectedOutcome: { type: String },
  actualOutcome: { type: String },
  financialImpact: {
    estimated: { type: Number, default: 0 },
    realized: { type: Number, default: 0 }
  },
  actionTaken: { type: String }, // e.g. "whatsapp_order", "ceo_brief", "none"
  ownerDecision: { type: String, enum: ['approved', 'overridden', 'pending'], default: 'pending' },
  overrideReason: { type: String },
  lessonLearned: { type: String },
  linkedPredictionLogId: { type: String },
  timestamp: { type: Date, default: Date.now }
});

// Aggregated, reusable lessons per shop/product/category, injected back into
// future OBSERVE/UNDERSTAND prompts so the agent doesn't repeat past mistakes.
const shopLessonSchema = new mongoose.Schema({
  id: { type: String, required: true },
  shopId: { type: String, required: true },
  productId: { type: String },
  category: { type: String },
  lesson: { type: String, required: true },
  sourceDecisionTraceId: { type: String },
  confidence: { type: Number, default: 1 }, // increments as the lesson is reconfirmed
  timestamp: { type: Date, default: Date.now }
});

// Add performance indexes for fast shopId and timestamp queries
productSchema.index({ shopId: 1, id: 1 });
customerSchema.index({ shopId: 1, id: 1 });
saleSchema.index({ shopId: 1, timestamp: -1 });
expenseSchema.index({ shopId: 1, timestamp: -1 });
complaintSchema.index({ shopId: 1, timestamp: -1 });
predictionLogSchema.index({ shopId: 1, timestamp: -1 });
actualLogSchema.index({ shopId: 1, timestamp: -1 });
decisionTraceSchema.index({ shopId: 1, cycleId: 1, timestamp: -1 });
shopLessonSchema.index({ shopId: 1, productId: 1 });

const Shop = mongoose.model('Shop', shopSchema);
const Product = mongoose.model('Product', productSchema);
const Customer = mongoose.model('Customer', customerSchema);
const Sale = mongoose.model('Sale', saleSchema);
const Expense = mongoose.model('Expense', expenseSchema);
const Complaint = mongoose.model('Complaint', complaintSchema);
const PredictionLog = mongoose.model('PredictionLog', predictionLogSchema);
const ActualLog = mongoose.model('ActualLog', actualLogSchema);
const ModelRegistry = mongoose.model('ModelRegistry', modelRegistrySchema);
const DecisionTrace = mongoose.model('DecisionTrace', decisionTraceSchema);
