const axios = require('axios');
const { GoogleGenAI } = require('@google/genai');
const db = require('../db').db;

const FASTAPI_URL = process.env.FASTAPI_URL || 'http://localhost:8000';
const GEMINI_MODELS = ['gemini-2.5-flash', 'gemini-2.0-flash', 'gemini-1.5-flash'];

const GOALS = {
  REDUCE_STOCKOUTS: 'reduce_stockouts',
  INCREASE_PROFIT: 'increase_profit',
  RECOVER_UDHAAR: 'recover_udhaar',
  REDUCE_DEAD_INVENTORY: 'reduce_dead_inventory'
};

// Owner-facing stage labels. Deliberately business language, never ADL/Mutagent terms.
const STAGE_LABELS = [
  { key: 'observe_inventory', label: 'Observing Inventory' },
  { key: 'observe_sales', label: 'Analyzing Sales' },
  { key: 'observe_weather', label: 'Checking Weather' },
  { key: 'observe_festival', label: 'Checking Festival Calendar' },
  { key: 'forecast', label: 'Running ML Forecast' },
  { key: 'evaluate', label: 'Comparing Yesterday' },
  { key: 'diagnose', label: 'Diagnosing Forecast Error' },
  { key: 'optimize', label: 'Optimizing Decisions' },
  { key: 'execute_order', label: 'Generating Purchase Order' },
  { key: 'execute_brief', label: 'Creating CEO Brief' },
  { key: 'execute_whatsapp', label: 'Preparing WhatsApp Order' },
  { key: 'learn', label: 'Learning From Outcomes' }
];

function getGenAI() {
  try { require('dotenv').config({ path: require('path').resolve(__dirname, '../.env'), override: true }); } catch (e) {}
  if (!process.env.GEMINI_API_KEY) return null;
  return new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
}

// Single Gemini call with the same model-fallback cascade used in routes/ai.js.
// Returns null when unavailable so every caller must supply a deterministic fallback.
async function askGemini(systemPrompt, userPrompt) {
  const ai = getGenAI();
  if (!ai) return null;
  for (const model of GEMINI_MODELS) {
    try {
      const result = await ai.models.generateContent({
        model,
        contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
        config: { systemInstruction: systemPrompt, maxOutputTokens: 1024, temperature: 0.4 }
      });
      if (result && result.text) return result.text;
    } catch (err) {
      console.warn(`[StoreManager] ${model} unavailable: ${err.message}`);
    }
  }
  return null;
}

function newId(prefix) {
  return `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

// ---------------------------------------------------------------------------
// STAGE 1 — OBSERVE
// ---------------------------------------------------------------------------

// Structured sibling of buildShopContext() in routes/ai.js. That one returns a
// Hinglish prose prompt for the chat model; this returns JSON the orchestrator
// can reason over programmatically.
async function observe(shopId) {
  const [products, sales, customers, expenses, lessons] = await Promise.all([
    db.products.find({ shopId }),
    db.sales.find({ shopId }),
    db.customers.find({ shopId }),
    db.expenses.find({ shopId }),
    db.shopLessons.find({ shopId }).sort({ timestamp: -1 }).limit(20)
  ]);

  const now = new Date();
  const todayKey = now.toISOString().split('T')[0];
  const yesterday = new Date(now.getTime() - 86400000);
  const yesterdayKey = yesterday.toISOString().split('T')[0];

  const todaySales = sales.filter(s => new Date(s.timestamp).toISOString().startsWith(todayKey));
  const yesterdaySales = sales.filter(s => new Date(s.timestamp).toISOString().startsWith(yesterdayKey));

  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  const monthSales = sales.filter(s => new Date(s.timestamp) >= monthStart);
  const monthRevenue = monthSales.reduce((sum, s) => sum + (s.amount || 0), 0);
  const monthExpenses = expenses
    .filter(e => new Date(e.timestamp) >= monthStart)
    .reduce((sum, e) => sum + (e.amount || 0), 0);

  // Units sold per product across the last 7 days, for velocity + dead stock.
  const weekAgo = new Date(now.getTime() - 7 * 86400000);
  const soldByProduct = {};
  for (const sale of sales) {
    if (new Date(sale.timestamp) < weekAgo) continue;
    for (const item of sale.items || []) {
      soldByProduct[item.productId] = (soldByProduct[item.productId] || 0) + (item.qty || 0);
    }
  }

  const lowStock = products
    .filter(p => (p.quantity || 0) <= (p.minStock || 5))
    .map(p => ({
      id: p.id,
      name: p.name,
      quantity: p.quantity || 0,
      minStock: p.minStock || 5,
      unit: p.unit,
      category: p.category,
      sellingPrice: p.sellingPrice,
      costPrice: p.costPrice,
      weeklyVelocity: soldByProduct[p.id] || 0
    }))
    .sort((a, b) => b.weeklyVelocity - a.weeklyVelocity);

  const deadStock = products
    .filter(p => (soldByProduct[p.id] || 0) === 0 && (p.quantity || 0) > 0)
    .map(p => ({
      id: p.id,
      name: p.name,
      quantity: p.quantity,
      lockedCapital: Math.round((p.quantity || 0) * (p.costPrice || 0))
    }))
    .sort((a, b) => b.lockedCapital - a.lockedCapital);

  const debtors = customers
    .filter(c => (c.totalCredit || 0) > 0)
    .map(c => ({ id: c.id, name: c.name, phone: c.phone, totalCredit: c.totalCredit, lastVisit: c.lastVisit }))
    .sort((a, b) => b.totalCredit - a.totalCredit);

  const totalCredit = debtors.reduce((sum, c) => sum + c.totalCredit, 0);

  return {
    shopId,
    generatedAt: now.toISOString(),
    dayOfWeek: now.toLocaleDateString('en-IN', { weekday: 'long' }),
    inventory: {
      totalProducts: products.length,
      lowStock,
      deadStock: deadStock.slice(0, 10),
      lockedCapital: deadStock.reduce((sum, p) => sum + p.lockedCapital, 0)
    },
    sales: {
      todayRevenue: Math.round(todaySales.reduce((s, x) => s + (x.amount || 0), 0)),
      todayBills: todaySales.length,
      yesterdayRevenue: Math.round(yesterdaySales.reduce((s, x) => s + (x.amount || 0), 0)),
      yesterdayBills: yesterdaySales.length,
      monthRevenue: Math.round(monthRevenue),
      monthExpenses: Math.round(monthExpenses),
      monthProfit: Math.round(monthRevenue - monthExpenses)
    },
    credit: { totalCredit: Math.round(totalCredit), debtors: debtors.slice(0, 5), debtorCount: debtors.length },
    context: { weather: getWeatherSignal(), festival: getFestivalSignal(now) },
    knownLessons: lessons.map(l => l.lesson)
  };
}

// Weather + festival signals. Kept as separate seams so the live weather feed
// (ml-service/fetch_weather.py) and a real festival calendar can drop in later
// without touching the orchestrator.
function getWeatherSignal() {
  const month = new Date().getMonth();
  const isMonsoon = month >= 5 && month <= 8;
  return {
    source: 'seasonal-heuristic',
    condition: isMonsoon ? 'rain_likely' : 'clear',
    note: isMonsoon
      ? 'Monsoon season — rain suppresses footfall but raises tea/milk/snack demand'
      : 'Clear season — normal footfall expected'
  };
}

const FESTIVALS = [
  { name: 'Diwali', month: 10, day: 20, demandLift: 0.35 },
  { name: 'Holi', month: 2, day: 14, demandLift: 0.25 },
  { name: 'Raksha Bandhan', month: 7, day: 19, demandLift: 0.2 },
  { name: 'Ganesh Chaturthi', month: 8, day: 7, demandLift: 0.22 }
];

function getFestivalSignal(now) {
  let nearest = null;
  for (const f of FESTIVALS) {
    let date = new Date(now.getFullYear(), f.month, f.day);
    if (date < now) date = new Date(now.getFullYear() + 1, f.month, f.day);
    const daysAway = Math.ceil((date - now) / 86400000);
    if (!nearest || daysAway < nearest.daysAway) nearest = { ...f, daysAway };
  }
  return {
    nearestFestival: nearest.name,
    daysAway: nearest.daysAway,
    isApproaching: nearest.daysAway <= 14,
    expectedDemandLift: nearest.daysAway <= 14 ? nearest.demandLift : 0
  };
}

// ---------------------------------------------------------------------------
// STAGE 2 — UNDERSTAND (set goals, name business problems)
// ---------------------------------------------------------------------------

// Goals are derived from the observed state so each decision has something
// concrete to move, rather than being generic automation.
function deriveGoals(ctx) {
  const goals = [];
  if (ctx.inventory.lowStock.length > 0) {
    goals.push({
      goal: GOALS.REDUCE_STOCKOUTS,
      priority: ctx.inventory.lowStock.length >= 3 ? 'high' : 'medium',
      rationale: `${ctx.inventory.lowStock.length} items at or below minimum stock`
    });
  }
  if (ctx.credit.totalCredit > 2000) {
    goals.push({
      goal: GOALS.RECOVER_UDHAAR,
      priority: ctx.credit.totalCredit > 5000 ? 'high' : 'medium',
      rationale: `₹${ctx.credit.totalCredit} outstanding across ${ctx.credit.debtorCount} customers`
    });
  }
  if (ctx.inventory.lockedCapital > 1000) {
    goals.push({
      goal: GOALS.REDUCE_DEAD_INVENTORY,
      priority: 'medium',
      rationale: `₹${ctx.inventory.lockedCapital} capital locked in non-moving stock`
    });
  }
  goals.push({
    goal: GOALS.INCREASE_PROFIT,
    priority: 'medium',
    rationale: `Month profit ₹${ctx.sales.monthProfit} on ₹${ctx.sales.monthRevenue} revenue`
  });
  return goals;
}

async function understand(ctx) {
  const goals = deriveGoals(ctx);
  const systemPrompt = `You are the store manager brain for an Indian kirana shop.
Given the shop state, list the top 3 business problems needing attention TODAY.
Think like a shop manager, not an engineer. Reply as a JSON array of objects:
[{"problem": "...", "goal": "reduce_stockouts|increase_profit|recover_udhaar|reduce_dead_inventory", "urgency": "high|medium|low"}]
Reply with JSON only, no markdown fences.`;

  const raw = await askGemini(systemPrompt, JSON.stringify({
    inventory: ctx.inventory,
    sales: ctx.sales,
    credit: ctx.credit,
    context: ctx.context,
    knownLessons: ctx.knownLessons
  }));

  let problems = null;
  if (raw) {
    try {
      problems = JSON.parse(raw.replace(/```json|```/g, '').trim());
    } catch (e) {
      console.warn('[StoreManager] understand(): could not parse Gemini JSON, using derived goals');
    }
  }
  if (!Array.isArray(problems) || problems.length === 0) {
    problems = goals.map(g => ({ problem: g.rationale, goal: g.goal, urgency: g.priority }));
  }
  return { goals, problems: problems.slice(0, 3), source: raw ? 'gemini' : 'derived' };
}

// ---------------------------------------------------------------------------
// STAGE 3 — EVALUATE (score yesterday's decisions against reality)
// ---------------------------------------------------------------------------

async function evaluatePastDecisions(shopId) {
  const priorDecisions = await db.decisionTraces
    .find({ shopId, stage: 'execute' })
    .sort({ timestamp: -1 })
    .limit(20);

  const scored = [];
  for (const decision of priorDecisions) {
    if (!decision.linkedPredictionLogId) continue;
    const actual = await db.actualLogs.findOne({ predictionLogId: decision.linkedPredictionLogId });
    if (!actual) continue;

    const prediction = await db.predictionLogs.findOne({ id: decision.linkedPredictionLogId });
    const predicted = prediction ? prediction.predictedDemand : null;
    // A forecast counts as a pass within 30% of what actually sold.
    const passed = actual.percentageError != null ? Math.abs(actual.percentageError) <= 30 : null;

    scored.push({
      decisionId: decision.id,
      decision: decision.decision,
      productName: actual.productName,
      predicted,
      actual: actual.actualSales,
      absoluteError: actual.absoluteError,
      percentageError: actual.percentageError,
      passed,
      ownerDecision: decision.ownerDecision,
      overrideReason: decision.overrideReason
    });
  }

  const withVerdict = scored.filter(s => s.passed !== null);
  return {
    total: scored.length,
    passed: withVerdict.filter(s => s.passed).length,
    failed: withVerdict.filter(s => !s.passed).length,
    passRate: withVerdict.length ? Math.round((withVerdict.filter(s => s.passed).length / withVerdict.length) * 100) : null,
    results: scored
  };
}

// ---------------------------------------------------------------------------
// STAGE 4 — DIAGNOSE (why did a recommendation fail?)
// ---------------------------------------------------------------------------

const FAILURE_TAXONOMY = [
  'weather_change', 'festival_impact_ignored', 'supplier_delay',
  'incorrect_confidence_threshold', 'weak_prompt', 'inventory_mismatch', 'seasonality'
];

async function diagnose(evaluation, ctx) {
  const failures = evaluation.results.filter(r => r.passed === false);
  const overrides = evaluation.results.filter(r => r.ownerDecision === 'overridden');
  if (failures.length === 0 && overrides.length === 0) {
    return { diagnoses: [], summary: 'No failed decisions to diagnose in this cycle.' };
  }

  const systemPrompt = `You diagnose why an Indian kirana store's demand forecast failed.
For each failure pick exactly one cause from: ${FAILURE_TAXONOMY.join(', ')}.
Give business reasoning, not AI/model jargon. Reply as JSON array only, no fences:
[{"productName":"...","cause":"<one of the taxonomy>","reasoning":"one business sentence","suggestedFix":"one concrete change"}]`;

  const raw = await askGemini(systemPrompt, JSON.stringify({
    failures, ownerOverrides: overrides, weather: ctx.context.weather, festival: ctx.context.festival
  }));

  let diagnoses = null;
  if (raw) {
    try { diagnoses = JSON.parse(raw.replace(/```json|```/g, '').trim()); } catch (e) { /* fall through */ }
  }
  if (!Array.isArray(diagnoses)) {
    // Deterministic fallback so a rate-limited Gemini never blanks the stage.
    diagnoses = failures.map(f => ({
      productName: f.productName,
      cause: f.percentageError > 0 ? 'incorrect_confidence_threshold' : 'seasonality',
      reasoning: f.percentageError > 0
        ? `Forecast overshot actual sales by ${Math.abs(Math.round(f.percentageError))}% — reorder quantity was too aggressive.`
        : `Forecast undershot actual sales by ${Math.abs(Math.round(f.percentageError))}% — demand was higher than modelled.`,
      suggestedFix: f.percentageError > 0
        ? 'Lower reorder quantity / raise confidence threshold for this item.'
        : 'Raise reorder quantity for this item on comparable days.'
    }));
  }
  return { diagnoses, summary: `${failures.length} failed decision(s), ${overrides.length} owner override(s) diagnosed.`, source: raw ? 'gemini' : 'heuristic' };
}

// ---------------------------------------------------------------------------
// STAGE 5 — OPTIMIZE (propose concrete parameter changes; never auto-applied)
// ---------------------------------------------------------------------------

function optimize(diagnosis, ctx) {
  const proposals = [];
  for (const d of diagnosis.diagnoses || []) {
    const product = ctx.inventory.lowStock.find(p => p.name === d.productName);
    if (d.cause === 'incorrect_confidence_threshold') {
      proposals.push({
        target: d.productName,
        parameter: 'reorder_quantity_multiplier',
        currentValue: 1.0,
        proposedValue: 0.8,
        reason: d.reasoning,
        expectedBenefit: 'Less capital locked in overstock'
      });
    } else if (d.cause === 'seasonality' || d.cause === 'weather_change') {
      proposals.push({
        target: d.productName,
        parameter: 'reorder_quantity_multiplier',
        currentValue: 1.0,
        proposedValue: 1.25,
        reason: d.reasoning,
        expectedBenefit: 'Fewer stockouts on high-demand days'
      });
    } else if (d.cause === 'festival_impact_ignored' && product) {
      proposals.push({
        target: d.productName,
        parameter: 'festival_demand_lift',
        currentValue: 0,
        proposedValue: ctx.context.festival.expectedDemandLift || 0.25,
        reason: d.reasoning,
        expectedBenefit: 'Festival demand accounted for in reorder'
      });
    }
  }
  return { proposals, applied: false, note: 'Proposals require owner approval before taking effect.' };
}

// ---------------------------------------------------------------------------
// SIMULATION — counterfactual attached to each recommendation
// ---------------------------------------------------------------------------

function simulateReorder(item, forecastQty) {
  const dailyVelocity = (item.weeklyVelocity || 0) / 7;
  const daysOfCover = dailyVelocity > 0 ? item.quantity / dailyVelocity : 99;
  const margin = (item.sellingPrice || 0) - (item.costPrice || 0);
  // Sales lost if we don't reorder: demand we can't serve before the next cycle.
  const unitsLostIfNoAction = Math.max(0, Math.round((7 - daysOfCover) * dailyVelocity));
  const lossIfNoAction = Math.round(unitsLostIfNoAction * margin);
  const profitIfAction = Math.round(forecastQty * margin);
  return {
    noActionOutcome: unitsLostIfNoAction > 0
      ? `Stockout in ~${Math.max(0, Math.round(daysOfCover))} day(s), approx ${unitsLostIfNoAction} sales lost`
      : 'Stock likely holds through the week',
    noActionImpact: -lossIfNoAction,
    actionOutcome: `Reorder ${forecastQty} ${item.unit || 'pc'} — covers the week`,
    actionImpact: profitIfAction
  };
}

// ---------------------------------------------------------------------------
// FORECAST — call the existing ML service, degrade to velocity heuristic
// ---------------------------------------------------------------------------

async function forecastItem(item, ctx) {
  try {
    const { data } = await axios.post(`${FASTAPI_URL}/predict/stockout`, {
      product_name: item.name,
      category: item.category,
      current_stock: item.quantity,
      price: item.sellingPrice,
      horizon_days: 7,
      is_holiday: ctx.context.festival.isApproaching
    }, { timeout: 8000 });

    const daily = data.daily_forecasts || [];
    const total = daily.reduce((sum, d) => sum + (d.predicted_demand || d.forecast || 0), 0);
    return {
      source: 'ml-service',
      weeklyDemand: Math.max(1, Math.round(total)),
      confidence: data.reorder?.confidence ? Math.round(data.reorder.confidence * 100) : 80,
      stockoutRisk: data.stockout?.will_stockout || false
    };
  } catch (err) {
    // ML service offline — fall back to observed weekly velocity plus signals.
    const lift = 1 + (ctx.context.festival.expectedDemandLift || 0);
    const base = Math.max(1, Math.round((item.weeklyVelocity || 1) * lift));
    return {
      source: 'velocity-heuristic',
      weeklyDemand: base,
      confidence: 60,
      stockoutRisk: item.quantity < base
    };
  }
}

// ---------------------------------------------------------------------------
// STAGE 6 — EXECUTE (produces pending decisions; owner approves before action)
// ---------------------------------------------------------------------------

async function execute(ctx, understanding, cycleId) {
  const decisions = [];

  // Reorder recommendations for low-stock items, ranked by velocity.
  for (const item of ctx.inventory.lowStock.slice(0, 5)) {
    const forecast = await forecastItem(item, ctx);
    const reorderQty = Math.max(forecast.weeklyDemand - item.quantity, forecast.weeklyDemand);
    const simulation = simulateReorder(item, reorderQty);

    const reason = [
      { factor: 'weekly_sales', value: `${item.weeklyVelocity} ${item.unit || 'pc'} sold last 7 days` },
      { factor: 'current_stock', value: `only ${item.quantity} ${item.unit || 'pc'} left (min ${item.minStock})` },
      { factor: 'forecast_source', value: forecast.source },
      { factor: 'weather', value: ctx.context.weather.note }
    ];
    if (ctx.context.festival.isApproaching) {
      reason.push({
        factor: 'festival',
        value: `${ctx.context.festival.nearestFestival} in ${ctx.context.festival.daysAway} days (+${Math.round(ctx.context.festival.expectedDemandLift * 100)}% demand)`
      });
    }

    const predictionLog = await db.predictionLogs.create({
      id: newId('pred'),
      shopId: ctx.shopId,
      productId: item.id,
      productName: item.name,
      predictedDemand: forecast.weeklyDemand,
      confidence: forecast.confidence,
      modelVersion: '7.0.0-hurdle',
      modelType: 'foundation'
    });

    decisions.push({
      id: newId('dec'),
      shopId: ctx.shopId,
      cycleId,
      stage: 'execute',
      goal: GOALS.REDUCE_STOCKOUTS,
      decision: `Order ${reorderQty} ${item.unit || 'pc'} ${item.name}`,
      reason,
      confidence: forecast.confidence,
      simulation,
      expectedOutcome: `Avoid stockout on ${item.name} for the next 7 days`,
      financialImpact: { estimated: simulation.actionImpact, realized: 0 },
      actionTaken: 'whatsapp_order',
      ownerDecision: 'pending',
      linkedPredictionLogId: predictionLog.id
    });
  }

  // Udhaar recovery for the largest debtors.
  for (const debtor of ctx.credit.debtors.slice(0, 3)) {
    if (debtor.totalCredit < 500) continue;
    const daysSinceVisit = debtor.lastVisit
      ? Math.floor((Date.now() - new Date(debtor.lastVisit)) / 86400000)
      : null;
    decisions.push({
      id: newId('dec'),
      shopId: ctx.shopId,
      cycleId,
      stage: 'execute',
      goal: GOALS.RECOVER_UDHAAR,
      decision: `Send payment reminder to ${debtor.name} for ₹${Math.round(debtor.totalCredit)}`,
      reason: [
        { factor: 'outstanding_credit', value: `₹${Math.round(debtor.totalCredit)}` },
        { factor: 'last_visit', value: daysSinceVisit != null ? `${daysSinceVisit} days ago` : 'never recorded' },
        { factor: 'share_of_total_udhaar', value: `${Math.round((debtor.totalCredit / Math.max(1, ctx.credit.totalCredit)) * 100)}% of all pending udhaar` }
      ],
      confidence: 85,
      simulation: {
        noActionOutcome: 'Credit ages further, recovery odds drop',
        noActionImpact: 0,
        actionOutcome: `Polite WhatsApp reminder — typical recovery ~60%`,
        actionImpact: Math.round(debtor.totalCredit * 0.6)
      },
      expectedOutcome: `Recover part of ₹${Math.round(debtor.totalCredit)} from ${debtor.name}`,
      financialImpact: { estimated: Math.round(debtor.totalCredit * 0.6), realized: 0 },
      actionTaken: 'whatsapp_reminder',
      ownerDecision: 'pending'
    });
  }

  // Dead stock clearance — free up locked capital.
  for (const dead of ctx.inventory.deadStock.slice(0, 2)) {
    if (dead.lockedCapital < 300) continue;
    decisions.push({
      id: newId('dec'),
      shopId: ctx.shopId,
      cycleId,
      stage: 'execute',
      goal: GOALS.REDUCE_DEAD_INVENTORY,
      decision: `Run a clearance discount on ${dead.name} (${dead.quantity} units)`,
      reason: [
        { factor: 'zero_sales', value: 'no units sold in the last 7 days' },
        { factor: 'locked_capital', value: `₹${dead.lockedCapital} tied up` }
      ],
      confidence: 70,
      simulation: {
        noActionOutcome: `₹${dead.lockedCapital} stays locked, risk of expiry`,
        noActionImpact: -dead.lockedCapital,
        actionOutcome: `Discounted clearance frees roughly ₹${Math.round(dead.lockedCapital * 0.8)}`,
        actionImpact: Math.round(dead.lockedCapital * 0.8)
      },
      expectedOutcome: `Convert dead stock into working capital`,
      financialImpact: { estimated: Math.round(dead.lockedCapital * 0.8), realized: 0 },
      actionTaken: 'clearance_discount',
      ownerDecision: 'pending'
    });
  }

  if (decisions.length) await db.decisionTraces.insertMany(decisions);
  return decisions;
}

// ---------------------------------------------------------------------------
// STAGE 7 — LEARN (turn outcomes and overrides into reusable lessons)
// ---------------------------------------------------------------------------

async function learn(shopId, evaluation, diagnosis, cycleId) {
  const lessons = [];

  for (const d of diagnosis.diagnoses || []) {
    const lesson = `${d.productName}: ${d.reasoning} → ${d.suggestedFix}`;
    lessons.push({
      id: newId('lesson'),
      shopId,
      lesson,
      sourceDecisionTraceId: cycleId
    });
  }

  // An owner override is as informative as a wrong forecast — capture why.
  const overridden = await db.decisionTraces.find({ shopId, ownerDecision: 'overridden', lessonLearned: null });
  for (const o of overridden) {
    const lesson = `Owner overrode "${o.decision}" — reason: ${o.overrideReason || 'not given'}. Weight this preference in future decisions.`;
    lessons.push({ id: newId('lesson'), shopId, lesson, sourceDecisionTraceId: o.id });
    await db.decisionTraces.updateOne({ id: o.id }, { $set: { lessonLearned: lesson } });
  }

  if (lessons.length) {
    await db.shopLessons.insertMany(lessons);
    await db.decisionTraces.create({
      id: newId('dec'),
      shopId,
      cycleId,
      stage: 'learn',
      decision: `Recorded ${lessons.length} lesson(s) from this cycle`,
      reason: lessons.map(l => ({ factor: 'lesson', value: l.lesson })),
      lessonLearned: lessons.map(l => l.lesson).join(' | ')
    });
  }

  return { lessonsLearned: lessons.map(l => l.lesson), count: lessons.length };
}

// ---------------------------------------------------------------------------
// CYCLE ORCHESTRATION
// ---------------------------------------------------------------------------

// Runs the full Observe→Learn cycle. onStage is called with each owner-facing
// stage label as it completes, so the UI can stream progress.
async function runCycle(shopId, onStage = () => {}) {
  const cycleId = newId('cycle');
  const startedAt = Date.now();
  const emit = (key, extra) => {
    const stage = STAGE_LABELS.find(s => s.key === key);
    onStage({ key, label: stage ? stage.label : key, status: 'done', ...extra });
  };

  const ctx = await observe(shopId);
  emit('observe_inventory', { detail: `${ctx.inventory.totalProducts} products, ${ctx.inventory.lowStock.length} low` });
  emit('observe_sales', { detail: `₹${ctx.sales.todayRevenue} today, ₹${ctx.sales.yesterdayRevenue} yesterday` });
  emit('observe_weather', { detail: ctx.context.weather.condition });
  emit('observe_festival', { detail: `${ctx.context.festival.nearestFestival} in ${ctx.context.festival.daysAway} days` });

  const understanding = await understand(ctx);
  const evaluation = await evaluatePastDecisions(shopId);
  emit('evaluate', {
    detail: evaluation.passRate != null
      ? `${evaluation.passed}/${evaluation.passed + evaluation.failed} past decisions on target (${evaluation.passRate}%)`
      : 'No prior decisions with recorded outcomes yet'
  });

  const diagnosis = await diagnose(evaluation, ctx);
  emit('diagnose', { detail: diagnosis.summary });

  const optimization = optimize(diagnosis, ctx);
  emit('optimize', { detail: `${optimization.proposals.length} improvement proposal(s)` });

  const decisions = await execute(ctx, understanding, cycleId);
  emit('forecast', { detail: `Forecast run for ${ctx.inventory.lowStock.slice(0, 5).length} item(s)` });
  emit('execute_order', { detail: `${decisions.filter(d => d.actionTaken === 'whatsapp_order').length} purchase order(s) drafted` });
  emit('execute_brief', { detail: 'CEO brief compiled' });
  emit('execute_whatsapp', { detail: `${decisions.filter(d => d.actionTaken === 'whatsapp_reminder').length} reminder(s) ready` });

  const learning = await learn(shopId, evaluation, diagnosis, cycleId);
  emit('learn', { detail: `${learning.count} lesson(s) recorded` });

  const executionTimeMs = Date.now() - startedAt;

  return {
    cycleId,
    executionTimeMs,
    context: ctx,
    goals: understanding.goals,
    problems: understanding.problems,
    evaluation,
    diagnosis,
    optimization,
    decisions,
    learning
  };
}

// "Today's Impact" summary — what the demo closes on.
async function getImpact(shopId, cycleId) {
  const query = cycleId ? { shopId, cycleId, stage: 'execute' } : { shopId, stage: 'execute' };
  const decisions = await db.decisionTraces.find(query);

  const approved = decisions.filter(d => d.ownerDecision === 'approved');
  const revenueSaved = approved.reduce((sum, d) => sum + (d.financialImpact?.realized || d.financialImpact?.estimated || 0), 0);
  const confidences = decisions.map(d => d.confidence).filter(c => typeof c === 'number');

  return {
    cycleId: cycleId || 'all-time',
    revenueSaved: Math.round(revenueSaved),
    revenueOpportunity: Math.round(decisions.reduce((sum, d) => sum + (d.financialImpact?.estimated || 0), 0)),
    stockoutsPrevented: approved.filter(d => d.goal === GOALS.REDUCE_STOCKOUTS).length,
    ordersGenerated: decisions.filter(d => d.actionTaken === 'whatsapp_order').length,
    udhaarRecovered: Math.round(approved.filter(d => d.goal === GOALS.RECOVER_UDHAAR)
      .reduce((sum, d) => sum + (d.financialImpact?.realized || d.financialImpact?.estimated || 0), 0)),
    decisionsPending: decisions.filter(d => d.ownerDecision === 'pending').length,
    avgConfidence: confidences.length ? Math.round(confidences.reduce((a, b) => a + b, 0) / confidences.length) : 0
  };
}

// Retrieval over stored traces — the owner's "why did you do that?" question is
// answered from the recorded reasoning, never re-generated by an LLM.
async function explainDecision(shopId, query) {
  const traces = await db.decisionTraces
    .find({ shopId, stage: 'execute' })
    .sort({ timestamp: -1 })
    .limit(50);

  const terms = String(query || '').toLowerCase().split(/\s+/).filter(t => t.length > 2);
  let best = null;
  let bestScore = 0;
  for (const t of traces) {
    const haystack = `${t.decision} ${(t.reason || []).map(r => `${r.factor} ${r.value}`).join(' ')}`.toLowerCase();
    const score = terms.filter(term => haystack.includes(term)).length;
    if (score > bestScore) { bestScore = score; best = t; }
  }

  if (!best) return { found: false, message: 'No matching decision found in the store history yet.' };
  return {
    found: true,
    decision: best.decision,
    goal: best.goal,
    confidence: best.confidence,
    reason: best.reason,
    simulation: best.simulation,
    expectedOutcome: best.expectedOutcome,
    actualOutcome: best.actualOutcome,
    lessonLearned: best.lessonLearned,
    ownerDecision: best.ownerDecision,
    decidedAt: best.timestamp
  };
}

module.exports = {
  runCycle,
  observe,
  understand,
  evaluatePastDecisions,
  diagnose,
  optimize,
  execute,
  learn,
  getImpact,
  explainDecision,
  GOALS,
  STAGE_LABELS
};

