const PORT = process.env.PORT || 5001;

// Scheduled Autonomous Store Manager run — same code path as the manual button,
// just a different trigger. Set STORE_MANAGER_SCHEDULE_HOUR to enable (0-23).
function startScheduledCycles() {
  const hour = parseInt(process.env.STORE_MANAGER_SCHEDULE_HOUR, 10);
  if (Number.isNaN(hour)) return;

  const { db } = require('./db');
  const storeManager = require('./services/storeManager');
  let lastRunDate = null;

  setInterval(async () => {
    const now = new Date();
    const dateKey = now.toISOString().split('T')[0];
    if (now.getHours() !== hour || lastRunDate === dateKey) return;
    lastRunDate = dateKey;

    try {
      const shops = await db.shops.find({ setupComplete: true });
      for (const shop of shops) {
        await storeManager.runCycle(shop.id);
        console.log(`🤖 Scheduled autonomous cycle completed for shop ${shop.id}`);
      }
    } catch (err) {
      console.error('Scheduled cycle failed:', err.message);
    }
  }, 60000);

  console.log(`   ⏰ Autonomous Store Manager scheduled daily at ${hour}:00`);
}

