import { useState, useRef } from 'react';
import { useStore } from '../context/StoreContext';
import {
  Play, CheckCircle2, Loader2, TrendingUp, PackageCheck, IndianRupee,
  Wallet, Gauge, Timer, HelpCircle, ThumbsUp, ThumbsDown, Brain, Lightbulb
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import api from '../api';
import './StoreManager.css';

const API_URL = import.meta.env.VITE_API_URL || '/api';

const GOAL_LABELS = {
  reduce_stockouts: { label: 'Stock Bachao', color: '#f59e0b' },
  increase_profit: { label: 'Munafa Badhao', color: '#10b981' },
  recover_udhaar: { label: 'Udhaar Wapas', color: '#ef4444' },
  reduce_dead_inventory: { label: 'Dead Stock Hatao', color: '#8b5cf6' }
};

export default function StoreManager() {
  const { showToast } = useStore();
  const [running, setRunning] = useState(false);
  const [stages, setStages] = useState([]);
  const [doneStages, setDoneStages] = useState([]);
  const [result, setResult] = useState(null);
  const [impact, setImpact] = useState(null);
  const [decisions, setDecisions] = useState([]);
  const [askQuery, setAskQuery] = useState('');
  const [answer, setAnswer] = useState(null);
  const bufferRef = useRef('');

  async function runCycle() {
    setRunning(true);
    setStages([]);
    setDoneStages([]);
    setResult(null);
    setImpact(null);
    setDecisions([]);
    setAnswer(null);
    bufferRef.current = '';

    try {
      const token = localStorage.getItem('antarya_token');
      const res = await fetch(`${API_URL}/store-manager/run`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Accept: 'text/event-stream',
          ...(token ? { Authorization: `Bearer ${token}` } : {})
        }
      });
      if (!res.ok || !res.body) throw new Error(`Server error (${res.status})`);

      const reader = res.body.getReader();
      const decoder = new TextDecoder();

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        bufferRef.current += decoder.decode(value, { stream: true });

        // SSE frames are separated by a blank line.
        const frames = bufferRef.current.split('\n\n');
        bufferRef.current = frames.pop();

        for (const frame of frames) {
          const eventLine = frame.split('\n').find(l => l.startsWith('event: '));
          const dataLine = frame.split('\n').find(l => l.startsWith('data: '));
          if (!eventLine || !dataLine) continue;
          const event = eventLine.slice(7).trim();
          const payload = JSON.parse(dataLine.slice(6));

          if (event === 'stages') setStages(payload);
          if (event === 'stage') setDoneStages(prev => [...prev, payload]);
          if (event === 'complete') {
            setResult(payload);
            setImpact(payload.impact);
            setDecisions(payload.decisions || []);
          }
          if (event === 'error') throw new Error(payload.detail || payload.error);
        }
      }
    } catch (err) {
      showToast?.(`Store Manager rukh gaya: ${err.message}`, 'error');
    } finally {
      setRunning(false);
    }
  }

  async function decide(decisionId, decision) {
    let reason;
    if (decision === 'overridden') {
      reason = window.prompt('Kyun nahi karna? (reason likhiye)');
      if (reason === null) return;
    }
    try {
      await api.approveDecision(decisionId, decision, reason);
      setDecisions(prev => prev.map(d => (d.id === decisionId ? { ...d, ownerDecision: decision } : d)));
      const fresh = await api.getStoreManagerImpact(result?.cycleId);
      setImpact(fresh);
      showToast?.(decision === 'approved' ? 'Approve ho gaya!' : 'Override save ho gaya — AI seekh lega', 'success');
    } catch (err) {
      showToast?.(err.message, 'error');
    }
  }

  async function ask() {
    if (!askQuery.trim()) return;
    try {
      setAnswer(await api.explainDecision(askQuery));
    } catch (err) {
      showToast?.(err.message, 'error');
    }
  }

  const pendingCount = decisions.filter(d => d.ownerDecision === 'pending').length;

  return (
    <div className="sm-wrap">
      <header className="sm-header">
        <div>
          <h1><Brain size={26} /> Apne Aap Chalne Wala Manager</h1>
          <p>Aapki dukaan ko roz subah khud check karta hai — stock, udhaar, aur munafa.</p>
        </div>
        <button className="sm-run-btn" onClick={runCycle} disabled={running}>
          {running ? <><Loader2 className="sm-spin" size={18} /> Chal raha hai...</> : <><Play size={18} /> Start Karein</>}
        </button>
      </header>

      {stages.length > 0 && (
        <section className="sm-stages">
          {stages.map(stage => {
            const done = doneStages.find(d => d.key === stage.key);
            return (
              <motion.div
                key={stage.key}
                className={`sm-stage ${done ? 'done' : 'waiting'}`}
                initial={{ opacity: 0, x: -8 }}
                animate={{ opacity: 1, x: 0 }}
              >
                <span className="sm-stage-icon">
                  {done ? <CheckCircle2 size={16} /> : <Loader2 size={16} className="sm-spin" />}
                </span>
                <span className="sm-stage-label">{stage.label}</span>
                {done?.detail && <span className="sm-stage-detail">{done.detail}</span>}
              </motion.div>
            );
          })}
        </section>
      )}

      {impact && (
        <motion.section className="sm-impact" initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }}>
          <h2>Aaj Ka Faayda</h2>
          <div className="sm-impact-grid">
            <ImpactTile icon={<IndianRupee size={18} />} label="Paisa Bacha" value={`₹${impact.revenueSaved}`} />
            <ImpactTile icon={<TrendingUp size={18} />} label="Mauka (Total)" value={`₹${impact.revenueOpportunity}`} />
            <ImpactTile icon={<PackageCheck size={18} />} label="Stockout Roka" value={impact.stockoutsPrevented} />
            <ImpactTile icon={<Wallet size={18} />} label="Udhaar Wapas" value={`₹${impact.udhaarRecovered}`} />
            <ImpactTile icon={<Gauge size={18} />} label="Bharosa" value={`${impact.avgConfidence}%`} />
            <ImpactTile icon={<Timer size={18} />} label="Lagaa Samay" value={`${((result?.executionTimeMs || 0) / 1000).toFixed(1)}s`} />
          </div>
          {pendingCount > 0 && <p className="sm-pending-note">{pendingCount} faisle aapki manzoori ka intezaar kar rahe hain.</p>}
        </motion.section>
      )}

      {decisions.length > 0 && (
        <section className="sm-decisions">
          <h2>AI Ke Faisle — Aap Decide Karein</h2>
          <AnimatePresence>
            {decisions.map(d => {
              const goal = GOAL_LABELS[d.goal] || { label: d.goal, color: '#64748b' };
              return (
                <motion.article key={d.id} className="sm-decision" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                  <div className="sm-decision-top">
                    <span className="sm-goal-chip" style={{ background: `${goal.color}22`, color: goal.color }}>{goal.label}</span>
                    <span className="sm-conf">{d.confidence}% sure</span>
                  </div>

                  <h3>{d.decision}</h3>

                  <ul className="sm-reasons">
                    {(d.reason || []).map((r, i) => (
                      <li key={i}><strong>{r.factor.replace(/_/g, ' ')}:</strong> {String(r.value)}</li>
                    ))}
                  </ul>

                  {d.simulation && (
                    <div className="sm-sim">
                      <div className="sm-sim-branch bad">
                        <span>Agar kuch na karein</span>
                        <p>{d.simulation.noActionOutcome}</p>
                        <strong>₹{d.simulation.noActionImpact}</strong>
                      </div>
                      <div className="sm-sim-branch good">
                        <span>Agar karein</span>
                        <p>{d.simulation.actionOutcome}</p>
                        <strong>+₹{d.simulation.actionImpact}</strong>
                      </div>
                    </div>
                  )}

                  {d.ownerDecision === 'pending' ? (
                    <div className="sm-actions">
                      <button className="sm-approve" onClick={() => decide(d.id, 'approved')}><ThumbsUp size={15} /> Haan, Karo</button>
                      <button className="sm-override" onClick={() => decide(d.id, 'overridden')}><ThumbsDown size={15} /> Nahi, Rehne Do</button>
                    </div>
                  ) : (
                    <div className={`sm-verdict ${d.ownerDecision}`}>
                      {d.ownerDecision === 'approved' ? '✅ Approve kiya' : '↩️ Aapne mana kiya — AI ne seekh liya'}
                    </div>
                  )}
                </motion.article>
              );
            })}
          </AnimatePresence>
        </section>
      )}

      {result?.learning?.lessonsLearned?.length > 0 && (
        <section className="sm-lessons">
          <h2><Lightbulb size={18} /> AI Ne Kya Seekha</h2>
          <ul>{result.learning.lessonsLearned.map((l, i) => <li key={i}>{l}</li>)}</ul>
        </section>
      )}

      <section className="sm-ask">
        <h2><HelpCircle size={18} /> Poochhiye — "aisa kyun kiya?"</h2>
        <div className="sm-ask-row">
          <input
            value={askQuery}
            onChange={e => setAskQuery(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && ask()}
            placeholder="jaise: chana kyun order kiya?"
          />
          <button onClick={ask}>Poochho</button>
        </div>
        {answer && (
          <div className="sm-answer">
            {answer.found ? (
              <>
                <h4>{answer.decision}</h4>
                <ul>
                  {(answer.reason || []).map((r, i) => (
                    <li key={i}><strong>{r.factor.replace(/_/g, ' ')}:</strong> {String(r.value)}</li>
                  ))}
                </ul>
                {answer.lessonLearned && <p className="sm-answer-lesson">Seekh: {answer.lessonLearned}</p>}
              </>
            ) : <p>{answer.message}</p>}
          </div>
        )}
      </section>
    </div>
  );
}

function ImpactTile({ icon, label, value }) {
  return (
    <div className="sm-tile">
      <span className="sm-tile-icon">{icon}</span>
      <span className="sm-tile-value">{value}</span>
      <span className="sm-tile-label">{label}</span>
    </div>
  );
}

