        <motion.section className="sm-impact" initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }}>
          <h2>Aaj Ka Faayda</h2>
          <div className="sm-impact-grid">
            <ImpactTile icon={<IndianRupee size={18} />} label="Paisa Bacha" value={`₹${impact.revenueSaved}`} />
            <ImpactTile icon={<TrendingUp size={18} />} label="Mauka (Total)" value={`₹${impact.revenueOpportunity}`} />
            <ImpactTile icon={<PackageCheck size={18} />} label="Stockout Roka" value={impact.stockoutsPrevented} />
            <ImpactTile icon={<Wallet size={18} />} label="Udhaar Wapas" value={`₹${impact.udhaarRecovered}`} />
            <ImpactTile icon={<Gauge size={18} />} label="Bharosa" value={`${impact.avgConfidence}%`} />
            <ImpactTile icon={<Timer size={18} />} label="Lagaa Samay" value={`${((result?.executionTimeMs || 0) / 1000).toFixed(1)}s`} />
          </div>
          {pendingCount > 0 && <p className="sm-pending-note">{pendingCount} faisle aapki manzoori ka intezaar kar rahe hain.</p>}
        </motion.section>
      )}

      {decisions.length > 0 && (
        <section className="sm-decisions">
          <h2>AI Ke Faisle — Aap Decide Karein</h2>
          <AnimatePresence>
            {decisions.map(d => {
              const goal = GOAL_LABELS[d.goal] || { label: d.goal, color: '#64748b' };
              return (
                <motion.article key={d.id} className="sm-decision" initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                  <div className="sm-decision-top">
                    <span className="sm-goal-chip" style={{ background: `${goal.color}22`, color: goal.color }}>{goal.label}</span>
                    <span className="sm-conf">{d.confidence}% sure</span>
                  </div>

                  <h3>{d.decision}</h3>

                  <ul className="sm-reasons">
                    {(d.reason || []).map((r, i) => (
                      <li key={i}><strong>{r.factor.replace(/_/g, ' ')}:</strong> {String(r.value)}</li>
                    ))}
                  </ul>

                  {d.simulation && (
                    <div className="sm-sim">
                      <div className="sm-sim-branch bad">
                        <span>Agar kuch na karein</span>
                        <p>{d.simulation.noActionOutcome}</p>
                        <strong>₹{d.simulation.noActionImpact}</strong>
                      </div>
                      <div className="sm-sim-branch good">
                        <span>Agar karein</span>
                        <p>{d.simulation.actionOutcome}</p>
                        <strong>+₹{d.simulation.actionImpact}</strong>
                      </div>
                    </div>
                  )}

                  {d.ownerDecision === 'pending' ? (
                    <div className="sm-actions">
                      <button className="sm-approve" onClick={() => decide(d.id, 'approved')}><ThumbsUp size={15} /> Haan, Karo</button>
                      <button className="sm-override" onClick={() => decide(d.id, 'overridden')}><ThumbsDown size={15} /> Nahi, Rehne Do</button>
                    </div>
                  ) : (
                    <div className={`sm-verdict ${d.ownerDecision}`}>
                      {d.ownerDecision === 'approved' ? '✅ Approve kiya' : '↩️ Aapne mana kiya — AI ne seekh liya'}
                    </div>
                  )}
                </motion.article>
              );
            })}
          </AnimatePresence>
        </section>
      )}

      {result?.learning?.lessonsLearned?.length > 0 && (
        <section className="sm-lessons">
          <h2><Lightbulb size={18} /> AI Ne Kya Seekha</h2>
          <ul>{result.learning.lessonsLearned.map((l, i) => <li key={i}>{l}</li>)}</ul>
        </section>
      )}

      <section className="sm-ask">
        <h2><HelpCircle size={18} /> Poochhiye — "aisa kyun kiya?"</h2>
        <div className="sm-ask-row">
          <input
            value={askQuery}
            onChange={e => setAskQuery(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && ask()}
            placeholder="jaise: chana kyun order kiya?"
          />
          <button onClick={ask}>Poochho</button>
        </div>
        {answer && (
          <div className="sm-answer">
            {answer.found ? (
              <>
                <h4>{answer.decision}</h4>
                <ul>
                  {(answer.reason || []).map((r, i) => (
                    <li key={i}><strong>{r.factor.replace(/_/g, ' ')}:</strong> {String(r.value)}</li>
                  ))}
                </ul>
                {answer.lessonLearned && <p className="sm-answer-lesson">Seekh: {answer.lessonLearned}</p>}
              </>
            ) : <p>{answer.message}</p>}
          </div>
        )}
      </section>
    </div>
  );
}

function ImpactTile({ icon, label, value }) {
  return (
    <div className="sm-tile">
      <span className="sm-tile-icon">{icon}</span>
      <span className="sm-tile-value">{value}</span>
      <span className="sm-tile-label">{label}</span>
    </div>
  );
}

input.content:
.sm-wrap {
  padding: 20px;
  max-width: 1100px;
  margin: 0 auto;
  padding-bottom: 90px;
}

.sm-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 22px;
}

.sm-header h1 {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 22px;
  font-weight: 700;
  color: #0f172a;
  margin: 0 0 4px;
}

.sm-header p {
  margin: 0;
  color: #64748b;
  font-size: 14px;
}

.sm-run-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 22px;
  border: none;
  border-radius: 12px;
  background: linear-gradient(135deg, #16a34a, #15803d);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  box-shadow: 0 4px 14px rgba(22, 163, 74, 0.3);
}

.sm-run-btn:disabled { opacity: 0.7; cursor: not-allowed; }

.sm-spin { animation: sm-rotate 1s linear infinite; }
@keyframes sm-rotate { to { transform: rotate(360deg); } }

/* Stage checklist */
.sm-stages {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 14px 16px;
  margin-bottom: 20px;
}

.sm-stage {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 0;
  font-size: 14px;
  border-bottom: 1px dashed #f1f5f9;
}

.sm-stage:last-child { border-bottom: none; }
.sm-stage.done .sm-stage-icon { color: #16a34a; }
.sm-stage.waiting { opacity: 0.5; }
.sm-stage.waiting .sm-stage-icon { color: #94a3b8; }

.sm-stage-icon { display: inline-flex; }
.sm-stage-label { font-weight: 600; color: #0f172a; }
.sm-stage-detail { color: #64748b; font-size: 13px; margin-left: auto; text-align: right; }

/* Impact card */
.sm-impact {
  background: linear-gradient(135deg, #0f172a, #1e293b);
  border-radius: 16px;
  padding: 20px;
  margin-bottom: 22px;
  color: #fff;
}

.sm-impact h2 { margin: 0 0 14px; font-size: 17px; font-weight: 700; }

.sm-impact-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 12px;
}

.sm-tile {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 12px;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.sm-tile-icon { color: #4ade80; }
.sm-tile-value { font-size: 20px; font-weight: 700; }
.sm-tile-label { font-size: 12px; color: #cbd5e1; }

.sm-pending-note { margin: 14px 0 0; font-size: 13px; color: #fbbf24; }

/* Decisions */
.sm-decisions h2, .sm-lessons h2, .sm-ask h2 {
  font-size: 17px;
  font-weight: 700;
  color: #0f172a;
  margin: 0 0 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.sm-decision {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 16px;
  margin-bottom: 14px;
}

.sm-decision-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.sm-goal-chip {
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 999px;
}

.sm-conf { font-size: 12px; color: #64748b; font-weight: 600; }

.sm-decision h3 { margin: 0 0 10px; font-size: 16px; font-weight: 700; color: #0f172a; }

.sm-reasons {
  list-style: none;
  padding: 0;
  margin: 0 0 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.sm-reasons li { font-size: 13px; color: #475569; }
.sm-reasons strong { color: #0f172a; text-transform: capitalize; }

/* Simulation branches */
.sm-sim {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-bottom: 12px;
}

.sm-sim-branch {
  border-radius: 10px;
  padding: 10px 12px;
  font-size: 13px;
}

.sm-sim-branch span { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.4px; }
.sm-sim-branch p { margin: 4px 0 6px; color: #475569; }
.sm-sim-branch strong { font-size: 15px; }

.sm-sim-branch.bad { background: #fef2f2; border: 1px solid #fecaca; }
.sm-sim-branch.bad span, .sm-sim-branch.bad strong { color: #dc2626; }

.sm-sim-branch.good { background: #f0fdf4; border: 1px solid #bbf7d0; }
.sm-sim-branch.good span, .sm-sim-branch.good strong { color: #16a34a; }

/* Approve / override */
.sm-actions { display: flex; gap: 10px; }

.sm-actions button {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 10px;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid transparent;
}

.sm-approve { background: #16a34a; color: #fff; }
.sm-override { background: #fff; color: #64748b; border-color: #e2e8f0 !important; }

.sm-verdict { font-size: 14px; font-weight: 600; padding: 9px; border-radius: 10px; text-align: center; }
.sm-verdict.approved { background: #f0fdf4; color: #16a34a; }
.sm-verdict.overridden { background: #fffbeb; color: #b45309; }

/* Lessons */
.sm-lessons {
  background: #fffbeb;
  border: 1px solid #fde68a;
  border-radius: 14px;
  padding: 16px;
  margin: 20px 0;
}

.sm-lessons ul { margin: 0; padding-left: 18px; }
.sm-lessons li { font-size: 13px; color: #78350f; margin-bottom: 5px; }

/* Ask-why */
.sm-ask {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 16px;
  margin-top: 20px;
}

.sm-ask-row { display: flex; gap: 10px; }

.sm-ask-row input {
  flex: 1;
  padding: 11px 14px;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  font-size: 14px;
  outline: none;
}

.sm-ask-row input:focus { border-color: #16a34a; }

.sm-ask-row button {
  padding: 11px 20px;
  border: none;
  border-radius: 10px;
  background: #0f172a;
  color: #fff;
  font-weight: 600;
  cursor: pointer;
}

.sm-answer {
  margin-top: 14px;
  padding: 14px;
  background: #f8fafc;
  border-radius: 10px;
}

.sm-answer h4 { margin: 0 0 8px; font-size: 15px; color: #0f172a; }
.sm-answer ul { list-style: none; padding: 0; margin: 0; }
.sm-answer li { font-size: 13px; color: #475569; margin-bottom: 3px; }
.sm-answer strong { color: #0f172a; text-transform: capitalize; }
.sm-answer-lesson { margin: 10px 0 0; font-size: 13px; color: #b45309; font-weight: 600; }

@media (max-width: 640px) {
  .sm-sim { grid-template-columns: 1fr; }
  .sm-stage-detail { display: none; }
  .sm-header { flex-direction: column; align-items: stretch; }
  .sm-run-btn { justify-content: center; }
}

