import { useLocation, useNavigate } from 'react-router-dom';
import { 
  Home, Package, Wallet, Users, Zap, Brain, 
  MessageSquare, Mic, Globe, LogOut, Store, Sparkles, ChevronRight, X
} from 'lucide-react';
import { useStore } from '../context/StoreContext';
import { motion, AnimatePresence } from 'framer-motion';
import { t } from '../utils/i18n';

const navLinks = [
  { path: '/dashboard', icon: Home, key: 'nav_dashboard', badgeKey: null },
  { path: '/decision-center', icon: Zap, key: 'nav_salah', badgeKey: 'badge_urgent' },
  { path: '/stock', icon: Package, key: 'nav_inventory', badgeKey: null },
  { path: '/sale', icon: Mic, key: 'nav_voice_pos', badgeKey: 'badge_fast' },
  { path: '/money', icon: Wallet, key: 'nav_cashbook', badgeKey: null },
  { path: '/customers', icon: Users, key: 'nav_customers', badgeKey: null },
  { path: '/learning-engine', icon: Brain, key: 'nav_learning', badgeKey: 'AI' },
  { path: '/ask', icon: MessageSquare, key: 'nav_ask_ai', badgeKey: null },
];

export default function Sidebar() {
  const location = useLocation();
  const navigate = useNavigate();
  const { shop, language, logout, sidebarOpen, closeSidebar } = useStore();

  const handleNavClick = (path) => {
    navigate(path);
    closeSidebar();
  };

  const sidebarContent = (
    <div className="flex flex-col h-full bg-[#0B0C10] border-r border-white/[0.08] w-[270px]">
      {/* Brand Logo & Header */}
      <div className="p-5 border-b border-white/[0.08] flex items-center justify-between">
        <div 
          className="flex items-center gap-3.5 cursor-pointer group" 
          onClick={() => handleNavClick('/dashboard')}
        >
          <div className="relative">
            <img 
              src="/antarya-logo.png" 
              alt="ANTARYA Logo" 
              className="w-10 h-10 rounded-xl object-cover border border-indigo-500/30 shadow-[0_0_16px_rgba(99,102,241,0.25)] transition-all duration-300 group-hover:border-indigo-400/60 group-hover:scale-105"
            />
            <span className="absolute -bottom-1 -right-1 w-3 h-3 rounded-full bg-emerald-500 border-2 border-[#0B0C10] shadow-[0_0_8px_#10b981]" />
          </div>
          <div>
            <div className="font-display font-black text-xl tracking-tight text-white group-hover:text-indigo-200 transition-colors">
              ANTARYA
            </div>
            <div className="text-[10px] font-bold text-indigo-400 tracking-wider uppercase flex items-center gap-1 mt-0.5">
              <Sparkles size={10} className="animate-pulse" /> DUKAN KA DIMAAG
            </div>
          </div>
        </div>

        {/* Mobile Close X button */}
        <button 
          onClick={closeSidebar}
          className="lg:hidden p-1.5 rounded-lg bg-white/[0.06] text-gray-400 hover:text-white transition-colors"
          aria-label="Close Sidebar"
        >
          <X size={18} />
        </button>
      </div>

      {/* Live AI Status Pill */}
      <div className="px-4 py-3">
        <div className="bg-emerald-500/10 border border-emerald-500/25 rounded-xl px-3.5 py-2 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="relative flex h-2 w-2">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
              <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
            </span>
            <span className="text-xs font-semibold text-emerald-400">AI Intelligence Active</span>
          </div>
          <span className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-emerald-500/20 text-emerald-300">
            100%
          </span>
        </div>
      </div>

      {/* Navigation Links */}
      <nav className="flex-1 px-3 py-2 overflow-y-auto space-y-1">
        <div className="text-[10px] font-bold text-gray-500 uppercase tracking-widest px-3 py-2">
          Navigation
        </div>
        {navLinks.map((link) => {
          const Icon = link.icon;
          const isActive = location.pathname === link.path;
          return (
            <motion.button
              key={link.path}
              whileHover={{ x: 3 }}
              whileTap={{ scale: 0.98 }}
              onClick={() => handleNavClick(link.path)}
              className={`w-full flex items-center justify-between px-3.5 py-2.5 rounded-xl font-medium text-sm transition-all duration-200 ${
                isActive
                  ? 'bg-gradient-to-r from-indigo-600/25 to-indigo-600/10 text-white font-semibold border-l-4 border-indigo-500 shadow-[0_4px_16px_rgba(99,102,241,0.15)]'
                  : 'text-gray-400 hover:text-gray-200 hover:bg-white/[0.04]'
              }`}
            >
              <div className="flex items-center gap-3">
                <Icon size={18} className={isActive ? 'text-indigo-400' : 'text-gray-400'} />
                <span>{t(link.key, language)}</span>
              </div>
              {link.badgeKey && (
                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                  link.badgeKey === 'badge_urgent'
                    ? 'bg-rose-500/20 text-rose-300 border border-rose-500/30'
                    : link.badgeKey === 'badge_fast'
                    ? 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/30'
                    : 'bg-purple-500/20 text-purple-300 border border-purple-500/30'
                }`}>
                  {link.badgeKey === 'AI' ? 'AI' : t(link.badgeKey, language)}
                </span>
              )}
            </motion.button>
          );
        })}
      </nav>

      {/* Store Profile Footer */}
      <div className="p-3 border-t border-white/[0.08] bg-black/30">
        <div className="flex items-center justify-between p-2 rounded-xl hover:bg-white/[0.04] transition-colors">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-lg bg-indigo-500/20 border border-indigo-500/30 flex items-center justify-center font-bold text-indigo-400 text-sm">
              {(shop?.name || 'S')[0]}
            </div>
            <div className="text-left overflow-hidden">
              <p className="text-xs font-bold text-white truncate max-w-[120px]">{shop?.name || 'My Kirana Shop'}</p>
              <p className="text-[11px] text-gray-400 truncate max-w-[120px]">{shop?.ownerName || 'Owner'}</p>
            </div>
          </div>

          <button 
            onClick={logout}
            className="p-2 text-gray-500 hover:text-rose-400 hover:bg-rose-500/10 rounded-lg transition-colors"
            title="Logout"
          >
            <LogOut size={16} />
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <>
      {/* Desktop Sticky Sidebar */}
      <aside className="hidden lg:flex desktop-sidebar">
        {sidebarContent}
      </aside>

      {/* Mobile / Tablet Drawer Overlay */}
      <AnimatePresence>
        {sidebarOpen && (
          <div className="lg:hidden fixed inset-0 z-50 flex">
            {/* Backdrop */}
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={closeSidebar}
              className="fixed inset-0 bg-black/70 backdrop-blur-sm"
            />

            {/* Slide-over Drawer Panel */}
            <motion.div
              initial={{ x: '-100%' }}
              animate={{ x: 0 }}
              exit={{ x: '-100%' }}
              transition={{ type: 'spring', damping: 25, stiffness: 200 }}
              className="relative z-10 h-full"
            >
              {sidebarContent}
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </>
  );
}

