// ---------------------------------------------------------------------------
// RECONCILE — close the loop between what we predicted and what actually sold
// ---------------------------------------------------------------------------

// Units of a product actually sold in [from, to), read off real sale line items.
function unitsSoldInWindow(sales, productId, from, to) {
  let units = 0;
  for (const sale of sales) {
    const ts = new Date(sale.timestamp);
    if (ts < from || ts >= to) continue;
    for (const item of sale.items || []) {
      if (item.productId === productId) units += item.qty || 0;
    }
  }
  return units;
}

const HORIZON_DAYS = 7;

// Without this, every prediction stays unscored forever and EVALUATE/DIAGNOSE/
// OPTIMIZE are permanently empty. Runs at the top of each cycle: any prediction
// whose 7-day horizon has elapsed gets an ActualLog written from real sales,
// using the same error maths as routes/learning.js.
async function reconcilePredictions(shopId) {
  const now = new Date();
  const cutoff = new Date(now.getTime() - HORIZON_DAYS * 86400000);

  const duePredictions = await db.predictionLogs.find({ shopId, timestamp: { $lte: cutoff } });
  if (!duePredictions.length) return { reconciled: 0 };

  const existing = await db.actualLogs.find({
    shopId,
    predictionLogId: { $in: duePredictions.map(p => p.id) }
  });
  const alreadyDone = new Set(existing.map(a => a.predictionLogId));

  const pending = duePredictions.filter(p => !alreadyDone.has(p.id));
  if (!pending.length) return { reconciled: 0 };

  const sales = await db.sales.find({ shopId });
  const rows = pending.map(p => {
    const from = new Date(p.timestamp);
    const to = new Date(from.getTime() + HORIZON_DAYS * 86400000);
    const actualSales = unitsSoldInWindow(sales, p.productId, from, to);
    const absoluteError = Math.abs(p.predictedDemand - actualSales);
    return {
      id: newId('actual'),
      shopId,
      productId: p.productId,
      productName: p.productName,
      actualSales,
      predictionLogId: p.id,
      absoluteError,
      // Percentage error is undefined against zero actuals — leave it null
      // rather than inventing a denominator.
      percentageError: actualSales > 0 ? ((p.predictedDemand - actualSales) / actualSales) * 100 : null,
      timestamp: to
    };
  });

  await db.actualLogs.insertMany(rows);
  return { reconciled: rows.length };
}

