// ---------------------------------------------------------------------------
// RECONCILE — close the loop between what we predicted and what actually sold
// ---------------------------------------------------------------------------

// Units of a product actually sold in [from, to), read off real sale line items.
function unitsSoldInWindow(sales, productId, from, to) {
  let units = 0;
  for (const sale of sales) {
    const ts = new Date(sale.timestamp);
    if (ts < from || ts >= to) continue;
    for (const item of sale.items || []) {
      if (item.productId === productId) units += item.qty || 0;
    }
  }
  return units;
}

