const express = require('express');
const router = express.Router();
const { authMiddleware: authenticate } = require('../middleware');
const db = require('../db').db;
const storeManager = require('../services/storeManager');

// POST /api/store-manager/run — execute one full autonomous cycle.
// Streams stage-by-stage progress via SSE when Accept: text/event-stream,
// otherwise returns the complete result in one response.
router.post('/run', authenticate, async (req, res) => {
  const wantsStream = req.headers.accept && req.headers.accept.includes('text/event-stream');

  if (!wantsStream) {
    try {
      const result = await storeManager.runCycle(req.shopId);
      const impact = await storeManager.getImpact(req.shopId, result.cycleId);
      return res.json({ ...result, impact });
    } catch (err) {
      console.error('[StoreManager] cycle failed:', err);
      return res.status(500).json({ error: 'Autonomous cycle failed', detail: err.message });
    }
  }

  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.flushHeaders?.();

  const send = (event, data) => res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
  send('stages', storeManager.STAGE_LABELS);

  try {
    const result = await storeManager.runCycle(req.shopId, stage => send('stage', stage));
    const impact = await storeManager.getImpact(req.shopId, result.cycleId);
    send('complete', { ...result, impact });
  } catch (err) {
    console.error('[StoreManager] cycle failed:', err);
    send('error', { error: 'Autonomous cycle failed', detail: err.message });
  } finally {
    res.end();
  }
});

// GET /api/store-manager/history — past cycles and their decisions
router.get('/history', authenticate, async (req, res) => {
  try {
    const traces = await db.decisionTraces
      .find({ shopId: req.shopId })
      .sort({ timestamp: -1 })
      .limit(200);

    const cycles = {};
    for (const t of traces) {
      if (!cycles[t.cycleId]) cycles[t.cycleId] = { cycleId: t.cycleId, timestamp: t.timestamp, decisions: [] };
      cycles[t.cycleId].decisions.push(t);
    }
    res.json({ cycles: Object.values(cycles) });
  } catch (err) {
    res.status(500).json({ error: 'Could not load history', detail: err.message });
  }
});

// POST /api/store-manager/approve — owner approves or overrides a decision.
// Nothing financially material executes until this is called.
router.post('/approve', authenticate, async (req, res) => {
  try {
    const { decisionId, decision, reason } = req.body;
    if (!decisionId || !['approved', 'overridden'].includes(decision)) {
      return res.status(400).json({ error: 'decisionId and decision ("approved"|"overridden") are required' });
    }

    const trace = await db.decisionTraces.findOne({ id: decisionId, shopId: req.shopId });
    if (!trace) return res.status(404).json({ error: 'Decision not found' });

    // Approval records intent only. financialImpact.realized stays untouched —
    // it is filled in by reconciliation once a real outcome confirms the value.
    const update = { ownerDecision: decision };
    if (decision === 'overridden') update.overrideReason = reason || 'No reason given';

    await db.decisionTraces.updateOne({ id: decisionId }, { $set: update });
    const updated = await db.decisionTraces.findOne({ id: decisionId });
    res.json({ success: true, decision: updated });
  } catch (err) {
    res.status(500).json({ error: 'Could not record approval', detail: err.message });
  }
});

// GET /api/store-manager/impact — "Today's Impact" summary card
router.get('/impact', authenticate, async (req, res) => {
  try {
    res.json(await storeManager.getImpact(req.shopId, req.query.cycleId));
  } catch (err) {
    res.status(500).json({ error: 'Could not compute impact', detail: err.message });
  }
});

// GET /api/store-manager/explain?query=... — answer "why did you do that?"
// straight from stored reasoning, not a fresh LLM call.
router.get('/explain', authenticate, async (req, res) => {
  try {
    res.json(await storeManager.explainDecision(req.shopId, req.query.query));
  } catch (err) {
    res.status(500).json({ error: 'Could not explain decision', detail: err.message });
  }
});

// GET /api/store-manager/lessons — accumulated shop lessons
router.get('/lessons', authenticate, async (req, res) => {
  try {
    const lessons = await db.shopLessons.find({ shopId: req.shopId }).sort({ timestamp: -1 }).limit(50);
    res.json({ lessons });
  } catch (err) {
    res.status(500).json({ error: 'Could not load lessons', detail: err.message });
  }
});

module.exports = router;

