.sm-wrap {
  padding: 20px;
  max-width: 1100px;
  margin: 0 auto;
  padding-bottom: 90px;
}

.sm-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 22px;
}

.sm-header h1 {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 22px;
  font-weight: 700;
  color: #0f172a;
  margin: 0 0 4px;
}

.sm-header p {
  margin: 0;
  color: #64748b;
  font-size: 14px;
}

.sm-run-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 22px;
  border: none;
  border-radius: 12px;
  background: linear-gradient(135deg, #16a34a, #15803d);
  color: #fff;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  box-shadow: 0 4px 14px rgba(22, 163, 74, 0.3);
}

.sm-run-btn:disabled { opacity: 0.7; cursor: not-allowed; }

.sm-spin { animation: sm-rotate 1s linear infinite; }
@keyframes sm-rotate { to { transform: rotate(360deg); } }

/* Stage checklist */
.sm-stages {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 14px 16px;
  margin-bottom: 20px;
