.sm-ask {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 16px;
  margin-top: 20px;
}

.sm-ask-row { display: flex; gap: 10px; }

.sm-ask-row input {
  flex: 1;
