// Units of a product actually sold in [from, to), read off real sale line items.
// Matches on productId or name — some historical sale rows carry line-item ids
// that predate the current product records, but the name is always present.
function unitsSoldInWindow(sales, productId, from, to, productName) {
  const target = productName ? productName.trim().toLowerCase() : null;
  let units = 0;
  for (const sale of sales) {
    const ts = new Date(sale.timestamp);
    if (ts < from || ts >= to) continue;
    for (const item of sale.items || []) {
      const matches = item.productId === productId ||
        (target && (item.name || '').trim().toLowerCase() === target);
      if (matches) units += item.qty || 0;
    }
  }
  return units;
}

