  if (q.includes('bill') || q.includes('photo') || q.includes('scan') || q.includes('receipt') || q.includes('invoice')) {
    return `📸 Bill Scan Karne Ka Tarika:\n• Bill ko flat rakhein aur clear photo lein — light acchi honi chahiye\n• Poora bill frame mein aaye, kono (corners) na katein\n• Blurry photo aane par dobara clear photo khinchein\n\nPhoto se items nikal kar aapke stock mein add ho jayenge. Abhi store mein ${products.length} products hain.`;
  }

  // Demand / forecasting questions, answered from this shop's own top sellers.
  if (q.includes('demand') || q.includes('forecast') || q.includes('kal') || q.includes('sunday') || q.includes('month') || q.includes('kitna') || q.includes('predict')) {
    const soldQty = {};
    for (const s of sales) {
      for (const it of s.items || []) soldQty[it.name] = (soldQty[it.name] || 0) + (it.qty || 0);
    }
    const top = Object.entries(soldQty).sort((a, b) => b[1] - a[1]).slice(0, 3);
    const topLine = top.length
      ? top.map(([n, qty]) => `• ${n}: ${qty} units bike`).join('\n')
      : `• Abhi tak sales record nahi hui — demand estimate ke liye kuch din ka data chahiye`;
    return `📈 Demand Ka Andaza (aapke apne sales data se):\n${topLine}\n\nWeekend aur month-start par ration items (atta, chawal, doodh, masala) ki demand badhti hai — in par extra stock rakhein. Store mein abhi ${products.length} products, ${lowStock.length} low stock par hain.`;
  }

  // Offline / resilience questions — explain what keeps working without internet.
  if (q.includes('offline') || q.includes('internet') || q.includes('net band') || q.includes('fallback') || q.includes('server down')) {
    return `📴 Offline Mode Mein Bhi Kaam Chalta Hai:\n• Bill banana aur sale record karna offline chalta hai\n• Stock aur udhaar khata local database se turant milta hai\n• Internet aane par sab data apne aap sync ho jata hai\n\nAbhi bhi main aapko real numbers de raha hoon — fallback engine seedha aapke database se padh raha hai: ${products.length} products, ₹${Math.round(totalCredit)} udhaar pending.`;
  }

  return `Namaste Boss! 🏪 Main aapki dukaan ka dimaag hoon.\n\nQuick Shop Summary:\n• Total Products: ${products.length}\n• Today's Revenue: ₹${Math.round(todayRevenue)}\n• Low Stock Alert: ${lowStock.length} items\n• Total Pending Udhaar: ₹${Math.round(totalCredit)}\n\nAap kuch bhi puchh sakte hain! 😊`;
}

