const metrics={
  team:'NIRVIKALP',
  hackathon:'HackIndia Spark-11 (CBIT Hyderabad)',
  track:'Mutagent Challenge Track',
  agentName:'antarya-dukan-ka-dimaag',
  evalSuite:'mutagent_eval_suite.json (20 cases, 6 categories)',
  methodology:'Every cycle is a real HTTP run against a live server hitting POST /api/ai/chat with a verified JWT. Pass requires >=1 expected keyword, >30 char response, and no error payload. No simulated or generated numbers.',
  adlProgression: cy.map((c,i)=>({
    cycle:i+1, name:c.cycleName, timestamp:c.timestamp,
    passRate:c.scorecard.passRate, passed:c.scorecard.passed, failed:c.scorecard.failed,
    avgLatencyMs:c.scorecard.avgLatencyMs,
    categoryBreakdown:Object.fromEntries(Object.entries(c.categoryBreakdown).map(([k,v])=>[k,v.pass+'/'+v.total])),
    failedScenarios:c.failedScenarios.map(f=>f.id)
  })),
  changesBetweenCycles:[
