  ],
  remainingFailures:{
    count:cy[2].scorecard.failed,
    ids:cy[2].failedScenarios.map(f=>f.id),
    honestNote:'These 5 remain genuinely unfixed. They expect product terms (butter, doodh, cheeni, lux soap, chai) that are not in the seeded 7-product fixture, or phrasing the deterministic fallback does not cover. We deliberately did not add keyword-specific branches to force a 100% score — that would optimise the scorecard rather than the product.'
  },
  knownLimitation:'Cycles 2 and 3 ran with the Gemini free-tier quota exhausted (avg latency <1s confirms the local fallback path served every request). The measured improvement is therefore an improvement in the OFFLINE resilience path, which is the path a real kirana shop hits most often on poor connectivity.'
};
fs.writeFileSync(P+'metrics.json',JSON.stringify(metrics,null,2));
console.log(JSON.stringify(metrics.adlProgression.map(c=>({cycle:c.cycle,pass:c.passRate,failed:c.failed})),null,1));
