const express = require('express');
const router = express.Router();
const axios = require('axios');
const { db } = require('../db');
const { authMiddleware } = require('../middleware');

// The FastAPI server runs on port 8000
const FASTAPI_URL = process.env.FASTAPI_URL || 'http://localhost:8000';

// Require authentication for all ML routes
router.use(authMiddleware);

/**
 * Proxy all requests from Express to FastAPI ML Service.
 * This keeps all our frontend calls pointed to a single backend (Express),
 * which then talks to the Python Microservice.
 */

// Route: /api/ml/predict
// FastAPI exposes /predict/demand and /predict/stockout — there is no bare
// /predict. Route on whether the caller supplied current_stock.
router.post('/predict', async (req, res) => {
    const target = req.body.current_stock != null ? '/predict/stockout' : '/predict/demand';
    try {
        const response = await axios.post(`${FASTAPI_URL}${target}`, req.body);
        res.json(response.data);
    } catch (error) {
        console.error(`ML Service Error (${target}):`, error.message);
        res.status(500).json({
            error: "Prediction failed",
            details: error.response?.data || error.message
        });
    }
});

// Explicit passthroughs matching the FastAPI surface.
router.post('/predict/demand', async (req, res) => {
    try {
        const response = await axios.post(`${FASTAPI_URL}/predict/demand`, req.body);
        res.json(response.data);
    } catch (error) {
        console.error("ML Service Error (/predict/demand):", error.message);
        res.status(500).json({ error: "Prediction failed", details: error.response?.data || error.message });
    }
});

router.post('/predict/stockout', async (req, res) => {
    try {
        const response = await axios.post(`${FASTAPI_URL}/predict/stockout`, req.body);
        res.json(response.data);
    } catch (error) {
        console.error("ML Service Error (/predict/stockout):", error.message);
        res.status(500).json({ error: "Prediction failed", details: error.response?.data || error.message });
    }
});

// Route: /api/ml/explain
router.post('/explain', async (req, res) => {
    try {
        const response = await axios.post(`${FASTAPI_URL}/explain`, req.body);
        res.json(response.data);
    } catch (error) {
        console.error("ML Service Error (/explain):", error.message);
        res.status(500).json({ 
            error: "Explanation failed", 
            details: error.response?.data || error.message 
        });
    }
});

// Route: /api/ml/decision
router.post('/decision', async (req, res) => {
    try {
        const response = await axios.post(`${FASTAPI_URL}/decision`, req.body);
        res.json(response.data);
    } catch (error) {
        console.error("ML Service Error (/decision):", error.message);
        res.status(500).json({ 
            error: "Decision engine failed", 
            details: error.response?.data || error.message 
        });
    }
});

// Route: /api/ml/ceo-brief
router.post('/ceo-brief', async (req, res) => {
    try {
        // Fetch the user's current inventory from the database
        const dbProducts = await db.products.find({ shopId: req.shopId });

        // If they have no products, return an empty brief
        if (!dbProducts || dbProducts.length === 0) {
            return res.json({
                generated_at: new Date().toISOString(),
                data_points: 0,
                prediction_runs: 0,
                actions: [],
                summary: { critical_alerts: 0, high_alerts: 0, total_actions: 0, products_analyzed: 0 },
                model_info: { type: "LightGBM", status: "No products in store" }
            });
        }

        // Map to the format FastAPI expects: { name, category, current_stock, price }
        const mappedProducts = dbProducts.map(p => ({
            name: p.name,
            category: p.category,
            current_stock: p.quantity,
            price: p.sellingPrice
        }));

        // Call FastAPI with the real data
        const response = await axios.post(`${FASTAPI_URL}/ceo-brief`, {
            products: mappedProducts,
            lead_time_days: 2,
            safety_stock: 5
        });

        // Asynchronously log the predictions for the learning engine
        if (response.data && response.data.actions) {
            try {
                const logs = response.data.actions.map(action => ({
                    id: require('uuid').v4(),
                    shopId: req.shopId,
                    productId: mappedProducts.find(p => p.name === action.product)?.id || 'unknown',
                    productName: action.product || 'Unknown Product',
                    predictedDemand: Number(action.prediction || action.predicted_units || action.daily_demand || action.suggested_reorder || 10),
                    confidence: 85, // Default confidence
                    modelVersion: '7.0.0-hurdle',
                    modelType: 'foundation',
                    timestamp: new Date()
                }));
                if (logs.length > 0) {
                    await db.predictionLogs.insertMany(logs);
                }
            } catch (logErr) {
                console.error("Silent error logging predictions:", logErr.message);
            }
        }

        res.json(response.data);
    } catch (error) {
        console.error("ML Service Error (/ceo-brief):", error.message);
        res.status(500).json({ 
            error: "CEO Brief failed", 
            details: error.response?.data || error.message 
        });
    }
});

// Route: /api/ml/health
router.get('/health', async (req, res) => {
    try {
        const response = await axios.get(`${FASTAPI_URL}/health`);
        res.json(response.data);
    } catch (error) {
        res.status(500).json({ 
            status: "down", 
            error: "FastAPI is not running. Start it with: cd ml-service && uvicorn main:app --port 8000" 
        });
    }
});

// Route: /api/ml/metrics
router.get('/metrics', async (req, res) => {
    try {
        const response = await axios.get(`${FASTAPI_URL}/metrics`);
        res.json(response.data);
    } catch (error) {
        res.status(500).json({ 
            error: "Failed to fetch metrics", 
            details: error.response?.data || error.message 
        });
    }
});

module.exports = router;

